setInterval(()=>{const e=$("#tq");if(e&&S&&!dq().f)e.textContent=left()},1000);
document.addEventListener("input",e=>{const id=e.target.id;if(!id||id.slice(0,3)!="bd_")return;const b=S&&tab=="body"?(BDW=BDW||{...getBd(),lim:[...getBd().lim]}):obd(),v=e.target.value;b[id.slice(3)]=id=="bd_x"?v:v===""?"":parseFloat(v)||0;const bt=$("#bdn");if(bt)bt.disabled=!bdOk(b)});
check();render();lbInit();ACC.boot();
